@namespace sv_e37102eb4f1149a79bedc9af17ef8645.Components.Chat

<div class="message-input-area">
    <textarea class="message-textarea"
              @bind="_text"
              @bind:event="oninput"
              @onkeydown="HandleKeyDown"
              placeholder="@Placeholder"
              rows="2"></textarea>
    <button class="send-btn" @onclick="Send" disabled="@string.IsNullOrWhiteSpace(_text)">
        @ButtonLabel
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSubmit { get; set; }

    private string _text = string.Empty;

    private async Task Send()
    {
        if (string.IsNullOrWhiteSpace(_text)) return;
        var message = _text.Trim();
        _text = string.Empty;
        await OnSubmit.InvokeAsync(message);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Send();
        }
    }
}

