toolArgs.file_text:
/* ===== Chat Layout ===== */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* ===== Channel Sidebar ===== */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d23;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #2d2f34;
}

.sidebar-title {
    padding: 1rem;
    margin: 0;
    font-size: 1rem;
    color: #fff;
    border-bottom: 1px solid #2d2f34;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 0.6rem 1rem;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s;
    position: relative;
}

.channel-item:hover {
    background: #2a2d35;
}

.channel-item.active {
    background: #2a2d35;
    border-left-color: #5865f2;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    color: #fff;
}

.channel-description {
    font-size: 0.75rem;
    color: #888;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 0.75rem;
    top: 50%;
    transform: translateY(-50%);
    background: #5865f2;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* ===== Main Message Area ===== */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #2b2d31;
    transition: width 0.2s;
}

.chat-main.with-thread {
    width: 55%;
    flex: none;
}

.chat-main.full-width {
    width: 80%;
    flex: 1;
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
}

.message-area-header {
    padding: 0.75rem 1.25rem;
    border-bottom: 1px solid #3a3c42;
    background: #2b2d31;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.message-area-header .channel-desc {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #888;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #888;
    font-size: 0.8rem;
}

/* ===== Message Bubble ===== */
.message-bubble {
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    position: relative;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.message-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #fff;
}

.message-time {
    font-size: 0.7rem;
    color: #72767d;
}

.message-content {
    margin-top: 0.2rem;
    color: #dcddde;
    font-size: 0.9rem;
    line-height: 1.4;
}

.message-reactions {
    display: flex;
    gap: 0.35rem;
    margin-top: 0.4rem;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #3a3c43;
    border: 1px solid #4a4c53;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dcddde;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #4a4c53;
}

.thread-link {
    background: none;
    border: none;
    color: #5865f2;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ===== Message Actions (hover) ===== */
.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #1e2024;
    border: 1px solid #3a3c42;
    border-radius: 6px;
    padding: 0.2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 0.75rem;
    padding: 0.3rem 0.5rem;
    cursor: pointer;
    border-radius: 4px;
}

.action-btn:hover {
    background: #3a3c43;
    color: #fff;
}

.emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #1e2024;
    border: 1px solid #3a3c42;
    border-radius: 6px;
    padding: 0.4rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem;
    border-radius: 4px;
}

.emoji-option:hover {
    background: #3a3c43;
}

/* ===== Message Input ===== */
.message-input-area {
    padding: 0.75rem 1rem;
    border-top: 1px solid #3a3c42;
    display: flex;
    gap: 0.5rem;
    align-items: flex-end;
    background: #2b2d31;
}

.message-textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 0.75rem;
    color: #dcddde;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

.message-textarea:focus {
    box-shadow: 0 0 0 2px #5865f2;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 0.6rem 1.2rem;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* ===== Thread Panel ===== */
.thread-panel {
    width: 25%;
    min-width: 280px;
    background: #232428;
    border-left: 1px solid #3a3c42;
    display: flex;
    flex-direction: column;
    height: 100vh;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3a3c42;
}

.thread-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.25rem 0.5rem;
    border-radius: 4px;
}

.close-btn:hover {
    background: #3a3c43;
    color: #fff;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3a3c42;
    background: #2a2c30;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.thread-reply {
    padding: 0.4rem 0;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}

